// EntryFilter provides filtering for Entry queries
type EntryFilter struct {
	Id          *UUIDFilter
	AmountCents *Int64Filter
	BookedOn    *DateFilter
	Kind        *StringFilter
	Memo        *StringFilter
	ExternalId  *StringFilter
	Tags        *ArrayStringFilter
	Metadata    *StringFilter
	ReviewedAt  *DateTimeFilter
	CreatedAt   *DateTimeFilter
	UpdatedAt   *DateTimeFilter
	// AccountID allows filtering by foreign key
	AccountID *UUIDFilter
	// TransferID allows filtering by foreign key
	TransferID *UUIDFilter
	// SearchText keeps the rows whose search fields hold each of its words,
	// in any case (D62): its runs of characters that are not White_Space,
	// the first 8 of them. Each word is a condition on the table's
	// search_text column, which the trigram index serves, ILIKE the word
	// with its \, % and _ escaped, so they match themselves. A text without
	// words, such as a blank one, keeps every row, and nil filters nothing.
	SearchText *string
}

// EntryUpdate provides fields that can be updated
type EntryUpdate struct {
	AmountCents       *types.GenericInt64
	BookedOn          *types.TemporalDate
	Kind              *types.EntryKind
	Memo              *string
	MemoSetNull       bool
	ExternalId        *string
	ExternalIdSetNull bool
	Tags              *[]string
	Metadata          *types.GenericJSON
	MetadataSetNull   bool
	ReviewedAt        *types.TemporalDateTime
	ReviewedAtSetNull bool
	// AccountID allows updating the foreign key for account
	AccountID *types.IdentityUUID
	// TransferID allows updating the foreign key for transfer
	TransferID        *types.IdentityUUID
	TransferIDSetNull bool
	// UpdatedBy is automatically set if not provided and user is in context
	UpdatedBy *types.IdentityUUID
}

// NewEntrySnapshotUpdate maps every mutable field from a complete
// Entry value. It is intended for source-of-truth replacement flows;
// nullable zero values clear their columns instead of leaving stale data.
func NewEntrySnapshotUpdate(input *types.Entry) *EntryUpdate {
	update := &EntryUpdate{}
	if input == nil {
		return update
	}
	update.AmountCents = &input.AmountCents
	update.BookedOn = &input.BookedOn
	update.Kind = &input.Kind
	var zeroMemo string
	if input.Memo == zeroMemo {
		update.MemoSetNull = true
	} else {
		update.Memo = &input.Memo
	}
	var zeroExternalId string
	if input.ExternalId == zeroExternalId {
		update.ExternalIdSetNull = true
	} else {
		update.ExternalId = &input.ExternalId
	}
	update.Tags = &input.Tags
	if input.Metadata == nil {
		update.MetadataSetNull = true
	} else {
		update.Metadata = input.Metadata
	}
	if input.ReviewedAt == nil {
		update.ReviewedAtSetNull = true
	} else {
		update.ReviewedAt = input.ReviewedAt
	}
	return update
}

// ApplyTo writes every set and SetNull field onto row. A nil receiver or row
// is a no-op. SetNull wins when both a value and SetNull are present.
func (u *EntryUpdate) ApplyTo(row *types.Entry) {
	if u == nil || row == nil {
		return
	}
	if u.AmountCents != nil {
		row.AmountCents = *u.AmountCents
	}
	if u.BookedOn != nil {
		row.BookedOn = *u.BookedOn
	}
	if u.Kind != nil {
		row.Kind = *u.Kind
	}
	if u.MemoSetNull {
		var zeroMemo string
		row.Memo = zeroMemo
	} else if u.Memo != nil {
		row.Memo = *u.Memo
	}
	if u.ExternalIdSetNull {
		var zeroExternalId string
		row.ExternalId = zeroExternalId
	} else if u.ExternalId != nil {
		row.ExternalId = *u.ExternalId
	}
	if u.Tags != nil {
		row.Tags = *u.Tags
	}
	if u.MetadataSetNull {
		row.Metadata = nil
	} else if u.Metadata != nil {
		row.Metadata = u.Metadata
	}
	if u.ReviewedAtSetNull {
		row.ReviewedAt = nil
	} else if u.ReviewedAt != nil {
		row.ReviewedAt = u.ReviewedAt
	}
	if u.AccountID != nil {
		row.Account.Id = u.AccountID
	}
	if u.TransferIDSetNull {
		row.Transfer = nil
	} else if u.TransferID != nil {
		if row.Transfer == nil {
			row.Transfer = &types.Account{}
		}
		row.Transfer.Id = u.TransferID
	}
	if u.UpdatedBy != nil {
		row.UpdatedBy = *u.UpdatedBy
	}
}

// EntryFilterConditions are the filter's conditions for a query of
// the caller's own, each column qualified by its table: each value is
// appended to args, its placeholder numbered after those already there.
// FindMany's WHERE is them joined by AND, then deleted_at IS NULL unless
// its options include deleted rows. That soft-delete condition is not
// among them: a query that leaves deleted rows out adds it itself. A nil
// filter has none.
func EntryFilterConditions(filter *EntryFilter, args *[]any) []string {
	return filter.conditions(args, len(*args))
}

// buildWhereClause builds a WHERE clause from a EntryFilter: its
// conditions joined by AND, or nothing when it has none.
func (f *EntryFilter) buildWhereClause(args *[]interface{}, paramOffset int) string {
	conditions := f.conditions(args, paramOffset)
	if len(conditions) == 0 {
		return ""
	}
	return " WHERE " + strings.Join(conditions, " AND ")
}

